// Internal identity switch on the real stack (WP-13b, M16; D2-AC-51 page and pool side; R-D2-38, R-D2-39; AWR-04 §15.9).
// Backend: perf/d21/live21.ts (tests/e2e/sbstack.py, N_max = 1) with a secret file generated by this spec at run time (random,
// 0600, removed afterwards; the deployment pass phrase appears nowhere). R79/R80 are show-api's (M11, WP-03b); until show-api
// serves them the stack puts tests/e2e/identity_standin.py in front: the comparison, rate limit, lockout, token and revocation
// list are the M17 identity library itself and the pool verifies the tokens for real (annotation `identity-backend`).
//   1. settings: the "advanced" section is folded; a wrong pass phrase shows "口令不正确"; the right one turns the header badge
//      to "内部 · 全功能"; the pass phrase is in no storage, page text, HTML or console line;
//   2. with the only public slot held by another visitor, the page opens its sandbox through the start Sheet: the session is
//      created on the reserved internal slot (no queue), its token carries `tier: internal` and an 8 h lifetime cap;
//   3. logout (R80): within 2 s the pool refuses the old identity token (401 302 identity_revoked);
//   4. five wrong attempts (spaced past the 0.5/s rate limit) and the sixth shows "尝试次数过多，请 30 分钟后再试".
// Round 2 (WP-03b delivered in D2-INT): R79/R80 must be show-api's (the stand-in only with M16_IDENTITY_STANDIN=1), and
//   5. the shared show of the public demo build (its visitors are viewers, so no page holds the seat; a test-build page of an
//      earlier case takes it as operator in loopback mode, hence the wait for FREE after its 30 s grace): with the identity
//      unlocked, the header badge's "申请控制" exchanges the identity token for a run admin token (R01 `identity_token`), the
//      seat is held, and a command goes through (Space: the show's clock is PAUSED per GET /api/sessions/current, then played
//      again and the seat released) (D2-AC-51 "共享展示可申请控制并下发命令");
//   6. the public demo bundle: `prod-bundle-scan.mjs <demo dist> --secret-file <a 0600 copy of this run's secret>` exits 0 (no
//      hidden internal entry in the viewer's first-screen chunks, the identity literal in one chunk, the secret in no file)
//      and prints no secret (D2-AC-51 "前端分块 0 处", M15-AC-227; d2-WP-11b-to-M16 item 6).
import { execFileSync } from 'node:child_process'
import { chmodSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { expect, test, type Page } from '@playwright/test'
import type { PreviewServer } from 'vite'
import {
  baseUrl, capacity, createSession, endSession, ensureBuild, isTestBuild, pageHeld, revealed, session, shot, skipOnboarding,
  startLive21, startLive21Preview, tokenPayload, waitPoolEmpty, watch, glyphScan, WEB, type Held, type Live21,
} from './live21'

const PORT = 4198
const DEMO_PORT = 4203
let live: Live21 | null = null
let server: PreviewServer | null = null
let demo: PreviewServer | null = null

test.use({ baseURL: baseUrl(PORT), viewport: { width: 1600, height: 900 }, locale: 'zh-CN' })
test.describe.configure({ mode: 'serial' })
test.beforeAll(async () => {
  test.setTimeout(600_000)
  const dist = ensureBuild('test')
  live = await startLive21({ maxSessions: 1, identity: true, releaseFrom: dist })
  server = await startLive21Preview(PORT, live, dist)
  demo = await startLive21Preview(DEMO_PORT, live, ensureBuild('demo'))
})
test.afterAll(async () => {
  await server?.close()
  await demo?.close()
  await live?.stop()
})

async function openSettings(page: Page): Promise<void> {
  await page.goto('/world/synthcity?reveal=shell&viewport=off&settings=general')
  await revealed(page)
  test.skip(!(await isTestBuild(page)), 'needs a test build')
  await expect(page.locator('[data-settings-advanced]')).toBeVisible({ timeout: 30_000 })
}

async function verify(page: Page, secret: string): Promise<void> {
  const input = page.locator('[data-identity-input]')
  if (!(await input.count())) await page.locator('[data-advanced-toggle]').click()
  await input.fill(secret)
  await page.locator('[data-identity-verify]').click()
  await expect(input).toHaveValue('')
}

async function scan(page: Page, secret: string, consoleLines: string[]): Promise<void> {
  const dump = await page.evaluate(() => {
    const all: string[] = []
    for (const st of [localStorage, sessionStorage]) for (let i = 0; i < st.length; i++) all.push(`${st.key(i)}=${st.getItem(st.key(i) ?? '')}`)
    return { storage: all.join('\n'), text: document.body.innerText, html: document.documentElement.outerHTML }
  })
  expect(dump.storage.includes(secret)).toBe(false)
  expect(dump.text.includes(secret)).toBe(false)
  expect(dump.html.includes(secret)).toBe(false)
  expect(consoleLines.join('\n').includes(secret)).toBe(false)
}

test('wrong and right pass phrase, badge, nothing kept; the internal sandbox takes the reserved slot; logout revokes', async ({ page }) => {
  test.setTimeout(420_000)
  test.info().annotations.push({ type: 'identity-backend', description: live!.identityBackend })
  if (process.env.M16_IDENTITY_STANDIN !== '1') expect(live!.identityBackend, 'R79/R80 served by show-api (WP-03b)').toBe('show-api')
  const secret = live!.secret!
  const w = watch(page)
  const bodies: string[] = []
  page.on('request', (r) => { if (r.url().includes('/api/auth/identity') && r.method() === 'POST') bodies.push(r.postData() ?? '') })
  await skipOnboarding(page)
  await openSettings(page)
  await expect(page.locator('[data-identity-input]')).toHaveCount(0)                    // folded by default
  await verify(page, `${secret}-wrong`)
  await expect(page.locator('[data-identity-error="wrong"]')).toHaveText('口令不正确', { timeout: 15_000 })
  await page.waitForTimeout(2200)                                                       // per-prefix rate 0.5/s
  await verify(page, secret)
  await expect(page.locator('[data-identity-section="internal"] [data-identity-badge]')).toHaveText('内部 · 全功能', { timeout: 15_000 })
  expect(bodies.length).toBe(2)
  await shot(page, 'd21-identity-live-ok')
  await scan(page, secret, w.console)
  await page.keyboard.press('Escape')
  await expect(page.locator('header [data-identity-badge]')).toBeVisible()
  const ident = await page.evaluate(() => JSON.parse(sessionStorage.getItem('awr.identity.v1') ?? 'null') as { token: string } | null)
  expect(ident?.token).toMatch(/^v1\./)
  const p = tokenPayload(ident!.token)
  expect(p.scope).toBe('identity')
  expect(p.role).toBe('internal')

  // the only public slot is held by another visitor; the internal sandbox is created on the reserved slot
  let pub: Held | null = null
  let mine: Held | null = null
  try {
    pub = await createSession(live!, 'MSIXIDENTPUBHINTAAAAAAAA', 't6_manual')
    await expect.poll(async () => String((await capacity(live!)).sandbox.state), { timeout: 10_000 }).toBe('full')
    await page.goto('/sandbox/sb-aaaaaaaaaa?reveal=shell&viewport=off')
    await revealed(page)
    await expect(page.locator('[data-sandbox-unavailable]')).toBeVisible({ timeout: 30_000 })
    await page.locator('[data-sandbox-unavailable] button').last().click()
    await expect(page.locator('[data-start-sheet]')).toBeVisible()
    await expect(page.locator('[data-template]')).toHaveCount(6, { timeout: 30_000 })
    await page.locator('[data-template="t6_manual"]').click()
    await page.locator('[data-start-go]').click()
    await expect(page).toHaveURL(/\/sandbox\/sb-[a-z2-7]{10}/, { timeout: 60_000 })
    await expect(page.locator('[data-session-bar]')).toBeVisible({ timeout: 60_000 })
    mine = await pageHeld(page)
    expect(mine).not.toBeNull()
    expect(tokenPayload(mine!.token).tier).toBe('internal')
    const s = await session(live!, mine!)
    expect((Number(BigInt(String(s.lifetime_max_unix_ns)) - BigInt(String(s.created_unix_ns))) / 1e9)).toBeGreaterThan(7200 + 3600)
    // the capacity answer is cached for up to 1 s by sandbox-api (and the pool's stats at 1 Hz): agree within 2 s (D2-AC-42)
    await expect.poll(async () => {
      const c = await capacity(live!)
      return `${Number(c.sandbox.active)}/${Number(c.sandbox.internal_active)}`
    }, { timeout: 5_000, intervals: [250] }).toBe('1/1')
    await shot(page, 'd21-identity-live-internal-sandbox')

    // logout: the old token is refused by the pool within 2 s
    await page.goto('/world/synthcity?reveal=shell&viewport=off&settings=general')
    await revealed(page)
    await page.locator('[data-advanced-toggle]').click()
    await page.locator('[data-identity-logout]').click()
    await page.locator('[data-identity-logout-confirm]').click()
    await expect(page.locator('[data-identity-form]')).toBeVisible()
    const t0 = Date.now()
    let why = ''
    await expect.poll(async () => {
      const r = await fetch(`${live!.base}/api/sandbox/v1/sessions`, { method: 'POST', headers: { 'content-type': 'application/json', 'x-awr-identity': ident!.token },
        body: JSON.stringify({ world: 'synthcity', template: 't6_manual', principal_hint: 'MSIXIDENTREVOKEDHINTAAAA' }) })
      const j = await r.json() as { code?: number; detail?: { why?: string }; session?: { sid: string }; token?: string }
      if (r.status === 201 && j.session && j.token) await endSession(live!, { sid: j.session.sid, token: j.token })
      why = String(j.detail?.why ?? r.status)
      return why
    }, { timeout: 5_000, intervals: [200] }).toBe('identity_revoked')
    expect(Date.now() - t0).toBeLessThanOrEqual(2500)
    expect(await page.evaluate(() => sessionStorage.getItem('awr.identity.v1'))).toBeNull()
    expect(await glyphScan(page)).toEqual([])
    await scan(page, secret, w.console)
    expect(w.errors).toEqual([])
  } finally {
    await endSession(live!, mine)
    await endSession(live!, pub)
    await waitPoolEmpty(live!).catch(() => null)
  }
})

/** the shared show's clock and seat (GET /api/sessions/current with a viewer token) */
async function showCurrent(): Promise<{ clock: { state: string }; seat: { state: string; holder_principal: string | null } }> {
  const t = await fetch(`${live!.showBase}/api/auth/token`, { method: 'POST', headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ role: 'viewer', principal_hint: 'MSIXIDENTSHOWVIEWAAAAAAA' }) })
  const tok = ((await t.json()) as { token: string }).token
  const r = await fetch(`${live!.showBase}/api/sessions/current`, { headers: { authorization: `Bearer ${tok}` } })
  return (await r.json()) as never
}

test('shared show (demo build): the identity requests control as admin and a command goes through', async ({ browser }) => {
  test.setTimeout(420_000)
  const secret = live!.secret!
  // the seat of an earlier test-build page (operator in loopback mode) is free after its 30 s grace
  await expect.poll(async () => (await showCurrent()).seat.state, { timeout: 90_000, intervals: [1000] }).toBe('FREE')
  const ctx = await browser.newContext({ baseURL: baseUrl(DEMO_PORT), viewport: { width: 1600, height: 900 }, locale: 'zh-CN' })
  const page = await ctx.newPage()
  const w = watch(page)
  await skipOnboarding(page)
  await page.goto('/world/synthcity?settings=general')
  await revealed(page)
  await expect(page.locator('[data-settings-advanced]')).toBeVisible({ timeout: 30_000 })
  await page.waitForTimeout(2200)
  await verify(page, secret)
  await expect(page.locator('[data-identity-section="internal"] [data-identity-badge]')).toHaveText('内部 · 全功能', { timeout: 15_000 })
  await page.keyboard.press('Escape')
  const badge = page.locator('header [data-identity-badge]')
  await expect(badge).toBeVisible({ timeout: 30_000 })
  expect((await showCurrent()).seat.state).toBe('FREE')                          // a demo visitor holds no seat
  await expect.poll(async () => (await showCurrent()).clock.state, { timeout: 30_000 }).toBe('PLAYING')
  await badge.click()
  await page.locator('[data-identity-control]').click()
  await expect(badge).toHaveAttribute('data-role', 'admin', { timeout: 15_000 })
  await expect(badge).toHaveAttribute('data-seat', 'held')
  await expect.poll(async () => (await showCurrent()).seat.state, { timeout: 10_000 }).not.toBe('FREE')
  await shot(page, 'd21-identity-live-shared-control')
  // a command: Space toggles the shared show's clock (sim/pause), then plays it again
  await page.keyboard.press('Escape')
  await page.evaluate(() => (document.activeElement as HTMLElement | null)?.blur())
  await page.keyboard.press('Space')
  await expect.poll(async () => (await showCurrent()).clock.state, { timeout: 15_000 }).toBe('PAUSED')
  await page.keyboard.press('Space')
  await expect.poll(async () => (await showCurrent()).clock.state, { timeout: 15_000 }).toBe('PLAYING')
  // release the seat (the header menu now offers "释放控制")
  await badge.click()
  await page.getByRole('menuitem', { name: '释放控制' }).click()
  await expect.poll(async () => (await showCurrent()).seat.state, { timeout: 10_000 }).toBe('FREE')
  await scan(page, secret, w.console)
  expect(w.errors).toEqual([])
  await ctx.close()
})

test('the public demo bundle: no hidden entry in the first screen, the secret in no file (prod-bundle-scan)', async () => {
  test.setTimeout(300_000)
  const demo = ensureBuild('demo')
  const dir = mkdtempSync(join(tmpdir(), 'awr-d21-scan-'))
  try {
    const f = join(dir, 'admin.secret')
    writeFileSync(f, `${live!.secret!}\n`, { mode: 0o600 })
    chmodSync(f, 0o600)
    let out = ''
    let code = 0
    try {
      out = execFileSync('node', [join(WEB, 'tests', 'm06', 'lint', 'prod-bundle-scan.mjs'), demo, '--secret-file', f], { cwd: WEB, encoding: 'utf8', stdio: 'pipe' })
    } catch (e) {
      const x = e as { status?: number; stdout?: string; stderr?: string }
      code = x.status ?? 1
      out = `${x.stdout ?? ''}${x.stderr ?? ''}`
    }
    test.info().annotations.push({ type: 'prod-bundle-scan', description: out.trim().split('\n').slice(-3).join(' | ') })
    expect(out.includes(live!.secret!)).toBe(false)
    expect(code, out).toBe(0)
  } finally {
    rmSync(dir, { recursive: true, force: true })
  }
})

test('five wrong attempts then the lock message', async ({ page }) => {
  test.setTimeout(300_000)
  const secret = live!.secret!
  const w = watch(page)
  await skipOnboarding(page)
  await openSettings(page)
  for (let i = 0; i < 5; i++) {
    await page.waitForTimeout(2200)
    await verify(page, `${secret}-${i}`)
    await expect(page.locator('[data-identity-error="wrong"]')).toBeVisible({ timeout: 15_000 })
  }
  await page.waitForTimeout(2200)
  await verify(page, secret)                                                        // locked: not compared even when right
  await expect(page.locator('[data-identity-error="locked"]')).toHaveText('尝试次数过多，请 30 分钟后再试', { timeout: 15_000 })
  await expect(page.locator('[data-identity-verify]')).toBeDisabled()
  await shot(page, 'd21-identity-live-locked')
  await scan(page, secret, w.console)
  expect(w.errors).toEqual([])
})
